from qgis.core import QgsProject, QgsLayerTreeLayer

project = QgsProject.instance()
root = project.layerTreeRoot()

target_name = "河南省市域"
target_layer = None

for layer in project.mapLayers().values():
    if layer.name() == target_name:
        target_layer = layer
        break

if target_layer is None:
    print(f"未找到图层: {target_name}")
else:
    # 使用 insertLayer 移动到索引 0（最底部）
    root.insertLayer(0, target_layer)
    print(f"已将图层 '{target_name}' 移动到最底部")

    # 验证当前图层顺序
    print("\n当前图层顺序（从底到顶）：")
    for i, child in enumerate(root.children()):
        if isinstance(child, QgsLayerTreeLayer):
            print(f"  [{i}] {child.layer().name()}")
